#include "../v9/net.h"
using namespace v9;
struct State{uint32_t seed;Board b;Preview p;Counts c;std::array<double,4> q,bq,base,pi;std::array<Projection,4> moves;bool valid;};
int main(int argc,char**argv){try{if(argc!=4)throw std::runtime_error("ARM SEED OUT");init();std::string arm=argv[1],out=argv[3];uint32_t seed=std::stoul(argv[2]);Net net;net.context=arm.find("context")!=std::string::npos;net.policy=arm.find("joint")!=std::string::npos;net.initialize(seed);Learner base;base.load("training/v7/base.ntd");std::ifstream file("training/v11/teacher.txt");std::vector<State>data;int won;State s;while(file>>s.seed>>won){for(auto&r:s.b){int x;file>>x;r=x;}file>>s.p.size;for(int i=0;i<3;i++){int r;file>>r>>s.p.p[i];s.p.cards[i]=r;}for(int&i:s.c)file>>i;for(auto&q:s.q)file>>q;if(!file)throw std::runtime_error("teacher data");double best=-1e300,sum=0;s.valid=(s.seed-11410001)%5==0;for(int d=0;d<4;d++){s.moves[d]=move(s.b,d);if(s.moves[d].size){s.base[d]=base.value(s.moves[d].b,stage(s.moves[d].b));s.bq[d]=s.moves[d].reward+s.base[d];best=std::max(best,s.q[d]);}}for(int d=0;d<4;d++){s.pi[d]=s.moves[d].size?std::exp(std::max(-30.,(s.q[d]-best)/2000)):0;sum+=s.pi[d];}for(auto&p:s.pi)p/=sum;data.push_back(s);}std::vector<int> train,validation;for(int i=0;i<int(data.size());i++)(data[i].valid?validation:train).push_back(i);if(train.empty()||validation.empty())throw std::runtime_error("empty split");std::mt19937 rng(seed);std::array<float,N>mom{},var{},grad{};int step=0;double bestLoss=1e300;std::filesystem::create_directories(out);std::ofstream log(out+"/metrics.jsonl");
 auto stateLoss=[&](const State&s,int sym,bool update){std::array<Features,4>fs;std::array<std::array<float,H>,4>hs;std::array<std::array<float,2>,4>os;std::array<double,4>logits{},ps{};double maxLog=-1e300,sum=0,huber=0,square=0,kl=0;int nv=0;for(int d=0;d<4;d++)if(s.moves[d].size){fs[d]=features(s.moves[d],s.p,s.c,s.base[d],net.context,sym);os[d]=net.forward(fs[d],&hs[d]);bool early=high(s.moves[d].b)<12;double correction=early?os[d][0]:0;logits[d]=s.bq[d]/2000+(net.policy?os[d][1]:4*correction);maxLog=std::max(maxLog,logits[d]);nv+=early;}for(int d=0;d<4;d++)if(s.moves[d].size){ps[d]=std::exp(logits[d]-maxLog);sum+=ps[d];}for(int d=0;d<4;d++)if(s.moves[d].size){ps[d]/=sum;kl+=s.pi[d]*(std::log(std::max(s.pi[d],1e-300))-std::log(std::max(ps[d],1e-300)));float dv=0;if(high(s.moves[d].b)<12){double err=os[d][0]-(s.q[d]-s.bq[d])/8000;huber+=(std::abs(err)<1?.5*err*err:std::abs(err)-.5)/std::max(1,nv);square+=err*err/std::max(1,nv);dv=0;}float dp=net.policy?(ps[d]-s.pi[d]):0;if(update)net.backward(fs[d],hs[d],dv,dp,grad);}return std::array<double,3>{huber,kl,square};};
 auto evaluate=[&](const std::vector<int>&indices){std::array<double,3>v{};for(int i:indices){auto x=stateLoss(data[i],0,false);for(int k=0;k<3;k++)v[k]+=x[k]/indices.size();}return v;};
 for(int epoch=0;epoch<=50;epoch++){if(epoch){std::shuffle(train.begin(),train.end(),rng);for(size_t begin=0;begin<train.size();begin+=16){grad.fill(0);int n=std::min<size_t>(16,train.size()-begin);for(int i=0;i<n;i++)stateLoss(data[train[begin+i]],rng()%8,true);step++;double c1=1-std::pow(.9,step),c2=1-std::pow(.999,step);for(int j=0;j<N;j++){float g=grad[j]/n;mom[j]=.9f*mom[j]+.1f*g;var[j]=.999f*var[j]+.001f*g*g;net.w[j]-=.001*(mom[j]/c1)/(std::sqrt(var[j]/c2)+1e-8);if(!std::isfinite(net.w[j]))throw std::runtime_error("diverged");}}}auto tr=evaluate(train),va=evaluate(validation);double loss=va[1];bool selected=loss<bestLoss;if(selected){bestLoss=loss;net.save(out+"/best.net");}log<<"{\"epoch\":"<<epoch<<",\"trainHuber\":"<<tr[0]<<",\"trainKL\":"<<tr[1]<<",\"trainRMSE\":"<<8000*std::sqrt(tr[2])<<",\"validationHuber\":"<<va[0]<<",\"validationKL\":"<<va[1]<<",\"validationRMSE\":"<<8000*std::sqrt(va[2])<<",\"selected\":"<<(selected?"true":"false")<<"}"<<std::endl;}
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
